using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class ToolUseChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var old=JsonUtility.FromJson<ToolDeliveryState>("{}");Check(old.Valid()&&old.proof?.used!=true&&!old.showUse,"Old handoff invented useful work");var p=new ToolUseProof{used=true,source="tree",newLearners=1,at=10};Check(p.Valid(),"Valid use rejected");p.stored=true;Check(!p.Valid(),"Stored proof without produce accepted");p.amount=3;Check(p.Valid()&&JsonUtility.FromJson<ToolUseProof>(JsonUtility.ToJson(p)).Valid(),"Stored proof did not save");p.newLearners=VillagePopulation.Adults;Check(!p.Valid(),"Unbounded audience accepted");var person=new ToolLearner{axeUses=1};Check(!person.Valid(),"Unowned axe use accepted");var s=new SliceState();string before=JsonUtility.ToJson(s);CreationBookText.Read(s,CreationBookSection.Creature,3);Check(before==JsonUtility.ToJson(s),"Book created work history");Debug.Log("BWVR_TOOL_USE_MODEL_PASS: legacy proof, bounded receipts, separate use/storage and read-only Book");}
 public static void VerifyRuntime(){
  Check(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var world=slice.GetComponentInChildren<VillageResources>();var god=slice.GetComponentInChildren<CreatureHybrid>();var nav=world.Navigation;Check(!nav.TreeNavigationPending,"Wait for navigation");var field=typeof(QuestSlice).GetField("state",F);var original=(SliceState)field.GetValue(slice);var people=world.Gatherers.Select(a=>a.GetComponent<VillagerSocial>()).ToArray();var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();var gp=god.transform.position;var gr=god.transform.rotation;var actor=world.Gatherers[2];var observer=world.Gatherers[1];var hidden=world.Gatherers[3];var hands=(CarryItem[])typeof(QuestSlice).GetField("held",F).GetValue(slice);Check(hands.All(i=>i==null),"Release hand objects");GameObject blocker=null;SliceState test=null;
  void Tick(float dt){if(!test.paused)test.Hybrid.time+=dt;actor.Tick(dt,test.paused);world.Advance(dt,test.paused);}
  bool PlaceViewer(VillagerResourceGathering viewer,Vector3 forbidden){for(int k=0;k<24;k++){var wanted=actor.transform.position+Quaternion.Euler(0,k*15,0)*Vector3.forward*nav.Scale*7;if(forbidden!=Vector3.zero&&Vector3.Dot((wanted-actor.transform.position).normalized,(forbidden-actor.transform.position).normalized)>.25f)continue;if(!viewer.GetComponent<IslandNavigator>().CanPlace(wanted,out var at))continue;viewer.transform.position=at;viewer.transform.LookAt(new Vector3(actor.transform.position.x,at.y,actor.transform.position.z));viewer.GetComponent<VillagerRoutine>().ResetTask();Physics.SyncTransforms();if(world.ProvisionVisible(viewer.GetComponent<VillagerSocial>(),actor.transform.position,actor.transform))return true;}return false;}
  try{
   god.Interrupt("Tool-use QA");foreach(var p in people){p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerBlockPlay>().ResetTask();p.ResetTask();slice.GetComponentInChildren<VillageFamilies>()?.Release(p.GetComponent<VillagerRoutine>());slice.GetComponentInChildren<VillageCathedral>()?.Cancel(p.GetComponent<VillagerRoutine>());p.GetComponent<CarryItem>().held=false;}
   test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100};test.resources=JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(world.State));test.Resources.wood=8;test.Resources.resin=4;test.Resources.wheat=30;test.Resources.freshFood=test.Resources.exposedWheat=0;for(int i=0;i<3;i++)test.Tools.Practice(0,1);field.SetValue(slice,test);god.NewSeason();world.ResetWorld();slice.SetSanctuaryOpen(false);foreach(var p in people){p.Memory.injury=0;p.Memory.lastFrightAt=-100;p.transform.position=world.StoreApproach+Vector3.up*nav.Scale*600;}god.transform.position=world.StoreApproach+Vector3.up*nav.Scale*800;Check(actor.GetComponent<IslandNavigator>().CanPlace(world.StoreApproach,out var stage),"No recipient stage");actor.transform.position=stage;actor.GetComponent<IslandNavigator>().ResetRoute();world.Advance(.01f,false);Check(world.Delivery?.Active==true&&world.Delivery.recipient==2,"No axe offering");Check((bool)typeof(QuestSlice).GetMethod("TryGrab",F).Invoke(slice,new object[]{1,world.DeliveryItem}),"Native tool pickup failed");typeof(QuestSlice).GetMethod("Release",F).Invoke(slice,new object[]{1,new Ray(actor.transform.position+Vector3.up*nav.Scale*30,Vector3.down)});var d=world.Delivery;Check(d.status==ToolDeliveryStatus.Delivered&&d.source==ToolDeliverySource.Player&&d.proof?.used!=true&&test.Resources.wood==6,"Delivery prematurely recorded useful work");
   for(int i=0;i<500&&actor.Source==null;i++)Tick(.05f);Check(actor.Source?.kind==VillageResource.Wood&&!test.Resources.Find(actor.Source.id).felled,"Recent axe did not autonomously choose actual needed standing wood");for(int i=0;i<2400&&actor.Current!=VillagerResourceGathering.Phase.Harvest;i++)Tick(.05f);Check(actor.Current==VillagerResourceGathering.Phase.Harvest,"Worker did not reach its tree");Check(PlaceViewer(observer,Vector3.zero),"No visible observer");Check(PlaceViewer(hidden,observer.transform.position),"No second viewer");blocker=new GameObject("QA physical view occluder",typeof(BoxCollider));blocker.transform.position=(actor.transform.position+hidden.transform.position)*.5f+Vector3.up*nav.Scale*2;blocker.GetComponent<BoxCollider>().size=new Vector3(2,8,2)*nav.Scale;Physics.SyncTransforms();Check(world.ProvisionVisible(observer.GetComponent<VillagerSocial>(),actor.transform.position,actor.transform)&&!world.ProvisionVisible(hidden.GetComponent<VillagerSocial>(),actor.transform.position,actor.transform),"Occluder did not isolate actual sightline");
   for(int i=0;i<200&&actor.Current!=VillagerResourceGathering.Phase.Carry;i++)Tick(.05f);Check(actor.Current==VillagerResourceGathering.Phase.Carry&&d.proof?.used==true&&!d.proof.stored&&test.Tools.learners[2].axeUses==1&&d.proof.newLearners==1&&test.Tools.learners[1].axeKnown&&!test.Tools.learners[1].axeOwned&&!test.Tools.learners[3].axeKnown&&test.Resources.wood==6,"Native use / seen-versus-hidden learning incorrect: phase="+actor.Current+" proof="+JsonUtility.ToJson(d.proof)+" uses="+test.Tools.learners[2].axeUses+" seen="+test.Tools.learners[1].axeKnown+" hidden="+test.Tools.learners[3].axeKnown+" stock="+test.Resources.wood);Check(!actor.RecordToolHarvest(VillageTool.BoundAxe,1)&&test.Tools.learners[2].axeUses==1,"Use receipt duplicated");test.paused=true;string paused=JsonUtility.ToJson(test);Tick(5);Check(paused==JsonUtility.ToJson(test),"Paused work changed proof");test.paused=false;string source=d.proof.source;actor.Cancel();Check(!d.proof.stored&&test.Resources.wood==6&&!world.RecordToolProduce(2,source,3),"Canceled cargo fabricated storage proof");UnityEngine.Object.DestroyImmediate(blocker);blocker=null;observer.transform.position+=Vector3.up*nav.Scale*600;hidden.transform.position+=Vector3.up*nav.Scale*600;Physics.SyncTransforms();
   for(int i=0;i<5000&&!d.proof.stored;i++)Tick(.05f);Check(d.proof.stored&&d.proof.amount==3&&test.Resources.wood==9&&d.source==ToolDeliverySource.Player&&!test.Hybrid.receipt.eligible&&test.Tools.woodSpent==2&&test.Tools.resinSpent==2,"Actual produce did not reach stores / attribution changed");Check(!world.RecordToolProduce(2,source,3),"Storage proof duplicated");var page=CreationBookText.Read(test,CreationBookSection.Creature,3);Check(page.text.Contains("New learners 1")&&page.text.Contains("3 wood reached stores"),"Book does not match confirmed work");
   typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);god.NewSeason();world.Advance(.01f,false);Check(test.Valid()&&test.Tools.delivery.proof.stored&&test.Tools.delivery.proof.amount==3&&test.Tools.learners[2].axeUses==1,"Native save lost work/learning evidence");Debug.Log("BWVR_TOOL_USE_RUNTIME_PASS: native player handoff, need-based autonomous axe work, physical seen/occluded observers, no free tools, use/storage separation, pause/cargo cancellation, real salvage delivery, unchanged source/cost/creature lessons and native save/Book evidence");
  }finally{if(blocker!=null)UnityEngine.Object.DestroyImmediate(blocker);god.Interrupt("Tool-use QA complete");foreach(var a in world.Gatherers)a.Cancel();for(int i=0;i<2;i++){if(hands[i]!=null){hands[i].held=false;hands[i].GetComponent<Collider>().enabled=true;hands[i]=null;}}field.SetValue(slice,original);god.NewSeason();world.ResetWorld();world.Advance(.01f,false);god.transform.SetPositionAndRotation(gp,gr);god.GetComponent<IslandNavigator>().ResetRoute();for(int i=0;i<people.Length;i++){people[i].GetComponent<CarryItem>().held=false;people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}Physics.SyncTransforms();}
 }
}
}
